// MemGuard X - open.mp component adapter.
// Connects the SDK-independent diagnostic engine to the open.mp server:
//   * configuration from config.json ("memguard.*" keys, generated by provideConfiguration)
//   * logging through ICore::logLn
//   * server tick -> periodic snapshots / reports / tick-interval statistics
//   * Pawn scripts -> native-call profiling and MemGuard_* natives (PawnBridge)
//   * pool components -> entity creation/destruction tracking (PoolWatcher)
//   * console command "memguard ..." (works from the server console and /rcon)
#include <sdk.hpp>

#include <Server/Components/Console/console.hpp>
#include <Server/Components/Pawn/pawn.hpp>

#include "../core/engine.hpp"
#include "../core/process_memory.hpp"
#include "pawn_bridge.hpp"
#include "pool_watchers.hpp"
#include "version.hpp"

#include <cstdio>
#include <memory>
#include <string>

using namespace memguard;

namespace {

::LogLevel toSdkLevel(memguard::LogLevel level)
{
	switch (level)
	{
	case memguard::LogLevel::Debug:
		return ::LogLevel::Debug;
	case memguard::LogLevel::Warning:
		return ::LogLevel::Warning;
	case memguard::LogLevel::Error:
		return ::LogLevel::Error;
	default:
		return ::LogLevel::Message;
	}
}

std::string toStd(StringView v)
{
	return std::string(v.data(), v.size());
}

constexpr const char* kPrefix = "memguard.";

} // namespace

class MemGuardComponent final : public IComponent,
								public CoreEventHandler,
								public PawnEventHandler,
								public ConsoleEventHandler
{
public:
	PROVIDE_UID(MEMGUARDX_COMPONENT_UID);

	MemGuardComponent()
		: engine_()
		, bridge_(engine_)
		, players_(engine_, "player")
		, vehicles_(engine_, "vehicle")
		, objects_(engine_, "object")
		, textLabels_(engine_, "textlabel")
		, pickups_(engine_, "pickup")
		, actors_(engine_, "actor")
		, gangZones_(engine_, "gangzone")
		, textDraws_(engine_, "textdraw")
		, menus_(engine_, "menu")
	{
	}

	~MemGuardComponent()
	{
		unregisterAll();
	}

	// ------------------------------------------------------------------ IComponent

	StringView componentName() const override { return "MemGuard X"; }

	SemanticVersion componentVersion() const override
	{
		return SemanticVersion(MEMGUARDX_VERSION_MAJOR, MEMGUARDX_VERSION_MINOR, MEMGUARDX_VERSION_PATCH, 0);
	}

	void provideConfiguration(ILogger& logger, IEarlyConfig& config, bool defaults) override
	{
		const Config d;
		for (const ConfigKeyInfo& info : configKeys())
		{
			const std::string key = std::string(kPrefix) + info.key;
			if (!defaults && config.getType(key) != ConfigOptionType_None)
			{
				continue; // keep the administrator's value
			}
			const std::string value = configValueAsString(d, info.key);
			switch (info.type)
			{
			case ConfigValueType::Bool:
				config.setBool(key, value == "true");
				break;
			case ConfigValueType::Int:
				config.setInt(key, std::stoi(value));
				break;
			case ConfigValueType::String:
				config.setString(key, value);
				break;
			}
		}
		(void)logger;
	}

	void onLoad(ICore* c) override
	{
		core_ = c;
		engine_.logger().setSink([this](memguard::LogLevel level, const std::string& msg) {
			if (core_)
			{
				core_->logLn(toSdkLevel(level), "%s", msg.c_str());
			}
		});

		loadConfiguration();

		const SemanticVersion v = core_->getVersion();
		char host[96];
		std::snprintf(host, sizeof(host), "open.mp %u.%u.%u.%u, %u-bit process", v.major, v.minor, v.patch, v.prerel,
			static_cast<unsigned>(sizeof(void*) * 8));
		engine_.setHostDescription(host);

		const Nanos overhead = Profiler::measureOverheadNs();
		engine_.setMeasuredProfilerOverhead(overhead);

		core_->getEventDispatcher().addEventHandler(this);
		coreHandlerAdded_ = true;
		if (engine_.config().trackPools)
		{
			players_.attach(core_->getPlayers().getPoolEventDispatcher(), nullptr);
		}

		char cost[32];
		formatDuration(overhead, cost, sizeof(cost));
		core_->logLn(::LogLevel::Message, "[MemGuardX] MemGuard X %s loaded (%s). Recording %s, native profiling %s, pool tracking %s. Profiler cost ~%s per instrumented call.",
			MEMGUARDX_VERSION_STRING, host, engine_.config().enabled ? "on" : "off", engine_.config().profileNatives ? "on" : "off",
			engine_.config().trackPools ? "on" : "off", cost);
	}

	void onInit(IComponentList* components) override
	{
		pawn_ = components->queryComponent<IPawnComponent>();
		if (pawn_)
		{
			bridge_.setPawnComponent(pawn_);
			pawn_->getEventDispatcher().addEventHandler(this);
		}
		else
		{
			engine_.logger().log(memguard::LogLevel::Warning, "[MemGuardX] Pawn component not found: native profiling and MemGuard_* natives unavailable.");
		}

		console_ = components->queryComponent<IConsoleComponent>();
		if (console_)
		{
			console_->getEventDispatcher().addEventHandler(this);
		}

		timers_ = components->queryComponent<ITimersComponent>();
		databases_ = components->queryComponent<IDatabasesComponent>();

		if (engine_.config().trackPools)
		{
			attachPool(vehicles_, components->queryComponent<IVehiclesComponent>());
			attachPool(objects_, components->queryComponent<IObjectsComponent>());
			attachPool(textLabels_, components->queryComponent<ITextLabelsComponent>());
			attachPool(pickups_, components->queryComponent<IPickupsComponent>());
			attachPool(actors_, components->queryComponent<IActorsComponent>());
			attachPool(gangZones_, components->queryComponent<IGangZonesComponent>());
			attachPool(textDraws_, components->queryComponent<ITextDrawsComponent>());
			attachPool(menus_, components->queryComponent<IMenusComponent>());
		}

		engine_.addMetricProvider("pawn", [this](std::vector<Metric>& out) { bridge_.collectMetrics(out); });
		engine_.addMetricProvider("server", [this](std::vector<Metric>& out) {
			if (timers_)
			{
				out.push_back(Metric { "server.timers", static_cast<std::int64_t>(timers_->count()), MetricKind::Count });
			}
			if (databases_)
			{
				out.push_back(Metric { "server.db_connections", static_cast<std::int64_t>(databases_->getDatabaseConnectionCount()), MetricKind::Count });
				out.push_back(Metric { "server.db_result_sets", static_cast<std::int64_t>(databases_->getDatabaseResultSetCount()), MetricKind::Count });
			}
		});
	}

	void onReady() override
	{
		engine_.takeSnapshot();
		engine_.logger().logf(memguard::LogLevel::Info, "[MemGuardX] Ready: %u pool watcher(s) active, Pawn integration %s. Type 'memguard help' in the console.",
			static_cast<unsigned>(attachedPools()), pawn_ ? "available" : "unavailable");
	}

	void onFree(IComponent* component) override
	{
		if (component == pawn_)
		{
			bridge_.detachAll();
			bridge_.setPawnComponent(nullptr);
			pawn_ = nullptr;
		}
		if (component == console_)
		{
			console_ = nullptr;
		}
		if (component == timers_)
		{
			timers_ = nullptr;
		}
		if (component == databases_)
		{
			databases_ = nullptr;
		}
		vehicles_.onComponentFree(component);
		objects_.onComponentFree(component);
		textLabels_.onComponentFree(component);
		pickups_.onComponentFree(component);
		actors_.onComponentFree(component);
		gangZones_.onComponentFree(component);
		textDraws_.onComponentFree(component);
		menus_.onComponentFree(component);
	}

	void free() override
	{
		if (core_)
		{
			std::string summary;
			if (engine_.config().enabled && engine_.config().reportIntervalSec != 0)
			{
				std::string error;
				summary = engine_.writeReport(error) ? (" Final report written to " + engine_.config().reportFile + ".") : (" Final report failed: " + error + ".");
			}
			const TrackerSnapshot ts = engine_.tracker().snapshot();
			core_->logLn(::LogLevel::Message, "[MemGuardX] MemGuard X shutting down: %u zones profiled, %llu tracked allocations still active, %llu confirmed tracking errors.%s",
				static_cast<unsigned>(engine_.profiler().zoneCount()), static_cast<unsigned long long>(ts.totalActive),
				static_cast<unsigned long long>(ts.totalTrackingErrors), summary.c_str());
		}
		delete this;
	}

	void reset() override
	{
		// Gamemode restart (GMX). Scripts are reloaded through onAmxUnload/onAmxLoad, pool
		// entities are destroyed through pool events; statistics are intentionally kept.
		// Memory is re-evaluated from a new baseline once the gamemode is loaded again (open.mp
		// loads it some seconds after the reset): its allocations are startup, not growth.
		restartPending_ = true;
	}

	// ------------------------------------------------------------------ CoreEventHandler

	void onTick(Microseconds, TimePoint) override
	{
		engine_.onTick();
		if (++ticksSinceHookCheck_ >= 1000)
		{
			ticksSinceHookCheck_ = 0;
			if (engine_.config().profileNatives)
			{
				const std::size_t n = bridge_.verifyHooks();
				if (n)
				{
					engine_.logger().logLimited(memguard::LogLevel::Debug, "rehook", "[MemGuardX] Re-installed the native-call hook on " + std::to_string(n) + " script(s).");
				}
			}
		}
	}

	// ------------------------------------------------------------------ PawnEventHandler

	void onAmxLoad(IPawnScript& script) override
	{
		if (restartPending_)
		{
			restartPending_ = false;
			engine_.markPhase("gamemode restart");
		}
		bridge_.setNativeProfiling(engine_.config().profileNatives);
		bridge_.attach(script);
	}

	void onAmxUnload(IPawnScript& script) override
	{
		bridge_.detach(script);
	}

	// ------------------------------------------------------------------ ConsoleEventHandler

	bool onConsoleText(StringView command, StringView parameters, const ConsoleCommandSenderData& sender) override
	{
		if (command != "memguard" && command != "mgx")
		{
			return false;
		}
		const std::string params = toStd(parameters);
		const bool profileBefore = engine_.config().profileNatives;
		const std::string reply = engine_.handleCommand(params);
		if (engine_.config().profileNatives != profileBefore)
		{
			bridge_.setNativeProfiling(engine_.config().profileNatives);
		}
		std::size_t pos = 0;
		while (pos < reply.size())
		{
			std::size_t nl = reply.find('\n', pos);
			if (nl == std::string::npos)
			{
				nl = reply.size();
			}
			const std::string line = reply.substr(pos, nl - pos);
			if (console_)
			{
				console_->sendMessage(sender, line);
			}
			else if (core_)
			{
				core_->printLn("%s", line.c_str());
			}
			pos = nl + 1;
		}
		return true;
	}

	void onConsoleCommandListRequest(FlatHashSet<StringView>& commands) override
	{
		commands.emplace("memguard");
	}

private:
	template <typename T, typename C>
	void attachPool(PoolWatcher<T>& watcher, C* component)
	{
		if (component)
		{
			watcher.attach(component->getPoolEventDispatcher(), component);
		}
	}

	std::size_t attachedPools() const
	{
		return static_cast<std::size_t>(players_.attached()) + vehicles_.attached() + objects_.attached() + textLabels_.attached()
			+ pickups_.attached() + actors_.attached() + gangZones_.attached() + textDraws_.attached() + menus_.attached();
	}

	void loadConfiguration()
	{
		IConfig& cfg = core_->getConfig();
		Config config;
		for (const ConfigKeyInfo& info : configKeys())
		{
			const std::string key = std::string(kPrefix) + info.key;
			std::string value;
			switch (cfg.getType(key))
			{
			case ConfigOptionType_Int:
				if (int* v = cfg.getInt(key))
				{
					value = std::to_string(*v);
				}
				break;
			case ConfigOptionType_Bool:
				if (bool* v = cfg.getBool(key))
				{
					value = *v ? "true" : "false";
				}
				break;
			case ConfigOptionType_String:
				value = toStd(cfg.getString(key));
				break;
			case ConfigOptionType_Float:
				if (float* v = cfg.getFloat(key))
				{
					value = std::to_string(static_cast<long long>(*v));
				}
				break;
			default:
				continue; // not present: keep default
			}
			std::string error;
			if (!applyConfigValue(config, info.key, value, error))
			{
				core_->logLn(::LogLevel::Warning, "[MemGuardX] Ignoring invalid config value %s: %s", key.c_str(), error.c_str());
			}
		}
		engine_.applyConfig(config);
		bridge_.setNativeProfiling(config.profileNatives);
	}

	void unregisterAll()
	{
		bridge_.detachAll();
		if (pawn_)
		{
			pawn_->getEventDispatcher().removeEventHandler(this);
			pawn_ = nullptr;
		}
		if (console_)
		{
			console_->getEventDispatcher().removeEventHandler(this);
			console_ = nullptr;
		}
		if (core_ && coreHandlerAdded_)
		{
			core_->getEventDispatcher().removeEventHandler(this);
			coreHandlerAdded_ = false;
		}
		players_.detach();
		vehicles_.detach();
		objects_.detach();
		textLabels_.detach();
		pickups_.detach();
		actors_.detach();
		gangZones_.detach();
		textDraws_.detach();
		menus_.detach();
	}

	ICore* core_ = nullptr;
	IPawnComponent* pawn_ = nullptr;
	IConsoleComponent* console_ = nullptr;
	ITimersComponent* timers_ = nullptr;
	IDatabasesComponent* databases_ = nullptr;
	bool coreHandlerAdded_ = false;
	unsigned ticksSinceHookCheck_ = 0;
	bool restartPending_ = false;

	Engine engine_;
	PawnBridge bridge_;
	PoolWatcher<IPlayer> players_;
	PoolWatcher<IVehicle> vehicles_;
	PoolWatcher<IObject> objects_;
	PoolWatcher<ITextLabel> textLabels_;
	PoolWatcher<IPickup> pickups_;
	PoolWatcher<IActor> actors_;
	PoolWatcher<IGangZone> gangZones_;
	PoolWatcher<ITextDraw> textDraws_;
	PoolWatcher<IMenu> menus_;
};

COMPONENT_ENTRY_POINT()
{
	return new MemGuardComponent();
}
